function profileScreenMessages<Index extends 0 | 1 | 2>(index: Index) {
  return Object.fromEntries(
    Object.entries(profileScreenMessageTable).map(([key, values]) => [key, values[index]]),
  ) as { [Key in keyof typeof profileScreenMessageTable]: (typeof profileScreenMessageTable)[Key][Index] };
}

