export const messages = {
  ru: { ...ru, "profile.blocked": "Заблокированные пользователи и жалобы" },
  kk: { ...kk, "profile.blocked": "Бұғатталған пайдаланушылар мен шағымдар" },
  en: { ...en, "profile.blocked": "Blocked users and complaints" },
} as const;

type SupportedLocale = keyof typeof messages;
type MessageParams = Record<string, string | number>;

function formatStoredMessage(locale: SupportedLocale, key: MessageKey, params?: MessageParams) {
  const value = messages[locale][key];
  return params ? value.replace(/\{(\w+)\}/g, (_, name) => String(params[name] ?? `{${name}}`)) : value;
}

export function localizedApiErrorForLocale(locale: SupportedLocale, error: unknown, fallback: string) {
  const detail = typeof error === "string" ? error.trim() : "";
  return locale === "ru" && detail ? detail : fallback;
}

const notificationBodyKeys = {
  friend_request: "notification.body.friendRequest",
  friendship_started: "notification.body.friendshipStarted",
  friend_rejected: "notification.body.friendRejected",
  new_message: "notification.body.newMessage",
  new_follower: "notification.body.newFollower",
  publication: "notification.body.publication",
  friendship_ended: "notification.body.friendshipEnded",
  like: "notification.body.like",
  comment: "notification.body.comment",
  event_submitted: "notification.body.eventSubmitted",
  event_moderation: "notification.body.eventModeration",
  event_reminder: "notification.body.eventReminder",
  author_book_activity: "notification.body.authorBookActivity",
  gift_reserved: "notification.body.giftReserved",
} as const satisfies Record<string, MessageKey>;

export function localizedNotificationText(locale: SupportedLocale, type: string, fallback: string, params: { name?: string } = {}) {
  const key = notificationBodyKeys[type as keyof typeof notificationBodyKeys];
  if (locale === "ru" || !key) return fallback;
  return formatStoredMessage(locale, key, { name: params.name?.trim() || formatStoredMessage(locale, "material.user") });
}

const storedNowValues = new Set([ru["common.now"], kk["common.now"], en["common.now"]].map((value) => value.toLocaleLowerCase()));
const storedTodayValues = new Set([ru["date.today"], kk["date.today"], en["date.today"], "сегодня"].map((value) => value.toLocaleLowerCase()));

export function localizedNotificationDate(locale: SupportedLocale, value: string) {
  const normalized = value.trim().toLocaleLowerCase();
  if (storedNowValues.has(normalized)) return formatStoredMessage(locale, "common.now");
  if (storedTodayValues.has(normalized)) return formatStoredMessage(locale, "date.today");
  return value;
}
